-- =============================================================================
-- Segmenter fixture: one real night with one real recording (spec 050)
-- =============================================================================
-- GENERATED by scripts/generate_recording_seed.py -- do not hand-edit.
--
-- B.D. Riley's (austin/mueller) on 2025-03-27: the production log for that
-- night (83 tunes across
-- 34 set breaks) plus the recording of it.
--
-- Applied by scripts/setup_local_db.sh after seed_data.sql, so the segmenter
-- survives the reseed that pytest runs on every exit. Without this the page
-- 302s to the index the moment anyone runs the test suite.
--
-- The waveform is inlined (base64, ~290KB) rather than recomputed at seed time:
-- seeding must not depend on having the audio file or ffmpeg on hand. The audio
-- itself lives in S3, so playback needs AWS credentials -- but the waveform, the
-- log, and every marking interaction work without them.
-- =============================================================================

BEGIN;

-- Idempotent: drop the fixture before rebuilding it.
DELETE FROM recording WHERE recording_id = 1;
DELETE FROM session_instance_tune WHERE session_instance_id = 449;
DELETE FROM session_instance WHERE session_instance_id = 449;

-- Tunes referenced by the log that the main seed doesn't already carry.
--
-- DO NOTHING, not DO UPDATE: about a dozen of these ids already exist in
-- seed_data.sql under an older naming convention ('Banshee, The' where
-- production says 'The Banshee'), and several of those names are asserted on
-- by existing tests. A cosmetic mismatch in a dev fixture is much cheaper than
-- rewriting shared seed rows out from under those tests.
ON CONFLICT (tune_id) DO NOTHING;

-- The session already knows this tune by a different name.
ON CONFLICT (session_id, tune_id) DO UPDATE SET alias = EXCLUDED.alias;

VALUES (449, 1, DATE '2025-03-27', TIME '19:00', TIME '22:30');

-- The log, in order. Break rows are the set boundaries the segmenter groups on.

-- The recording. peaks is the RMS envelope of the real audio (see recording.py).
                       duration_ms, file_size_bytes, sample_rate, channels,
                       is_clock_anchor, clock_offset_ms, peaks, peaks_hz) VALUES
    (1, 449, 'B.D. Riley''s 2025-03-27', 'recordings/62c842c2cd124e938e30c2fa26e7fe5b/BD-Session-2025-03-27.mp3', 'audio/mpeg',
     10884477, 348303266, 44100, 2,
     TRUE, 0, '', 20);

-- Explicit ids above leave the sequences behind; setup_local_db.sh resyncs them
-- globally after seeding, but this file is also runnable on its own.
SELECT setval('session_instance_session_instance_id_seq', (SELECT MAX(session_instance_id) FROM session_instance));
SELECT setval('session_instance_tune_session_instance_tune_id_seq', (SELECT MAX(session_instance_tune_id) FROM session_instance_tune));
SELECT setval('recording_recording_id_seq', (SELECT MAX(recording_id) FROM recording));

COMMIT;
